contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address arg) public payable {
        require(true);

        uint balanceBefore = address(c).balance;
        uint callerBalanceBefore = c.balances(address(this)); if (__ESBMC_reverted()) return;

        bool reverted;
        c.SetLogFile(arg); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        assert(address(c).balance == balanceBefore && c.balances(address(this)) == callerBalanceBefore);
    }

    receive() external payable {}
}

