pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ACCURAL_DEPOSIT} from "../src/ACCURAL_DEPOSIT.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ACCURAL_DEPOSIT c;

    function setUp() public {
        c = new ACCURAL_DEPOSIT();
    }

    function _run(address arg) internal {
        vm.assume(true);
        uint balanceBefore = address(c).balance;
        uint256 callerBalanceBefore;
        try c.balances(address(this)) returns (uint256 __r) { callerBalanceBefore = __r; } catch { return; }
        bool reverted;
        try c.SetLogFile(arg) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(address(c).balance == balanceBefore && c.balances(address(this)) == callerBalanceBefore);
    }

    function testFuzz_run(address arg) public {
        vm.assume(arg.code.length == 0 && uint160(arg) > 0xffff && arg != address(this) && arg != address(c) && arg != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && arg != 0x000000000000000000636F6e736F6c652e6c6f67 && arg != 0x4e59b44847b379578588920cA78FbF26c0B4956C && arg != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(arg);
    }

    receive() external payable {}
}
